<# AIIO Case Workspace V3 WPF integration. Loaded before XAML; initialized lazily. #>
$Script:PMMAIIOCaseUI=@{}
$Script:PMMAIIOCaseSelectedId=''
$Script:PMMAIIOCaseWorkspaceInitialized=$false
$Script:PMMAIIOCaseWorkspaceInitializing=$false
$Script:PMMAIIOCaseOriginalGetSessions=${function:Get-PMMAIIOSessions}

function Get-PMMAIIOCaseControl([string]$Name){if($Script:PMMAIIOCaseUI.ContainsKey($Name)){return $Script:PMMAIIOCaseUI[$Name]};return $null}
function Set-PMMAIIOCaseUiStatus([string]$Text){$c=Get-PMMAIIOCaseControl 'TxtStatus';if($c){$c.Text=$Text};try{$Script:TxtStatus.Text=$Text}catch{}}
function Get-PMMAIIOSelectedCase{if(-not$Script:PMMAIIOCaseSelectedId){return $null};return (Get-PMMAIIOCase $Script:PMMAIIOCaseSelectedId)}

function New-PMMAIIOCaseWorkspaceTab{
$x=@'
<TabItem xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml" Header="AIIO cases">
<Grid Margin="8">
 <Grid.ColumnDefinitions><ColumnDefinition Width="0.9*" MinWidth="300"/><ColumnDefinition Width="7"/><ColumnDefinition Width="2.8*" MinWidth="620"/></Grid.ColumnDefinitions>
 <Border Grid.Column="0" Background="{DynamicResource CardAltBackground}" BorderBrush="{DynamicResource CardBorder}" BorderThickness="1" CornerRadius="6" Padding="8">
  <Grid><Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="*"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
   <DockPanel Margin="0,0,0,6"><StackPanel DockPanel.Dock="Left"><TextBlock Text="Cases" FontSize="16" FontWeight="SemiBold"/><TextBlock Text="Newest first" Foreground="{DynamicResource MutedText}"/></StackPanel><Button x:Name="BtnNew" DockPanel.Dock="Right" Content="+ New case"/></DockPanel>
   <DataGrid x:Name="DgCases" Grid.Row="1" AutoGenerateColumns="False" IsReadOnly="True" SelectionMode="Single" SelectionUnit="FullRow" CanUserAddRows="False" Margin="0,2,0,6"><DataGrid.Columns><DataGridTextColumn Header="Case" Binding="{Binding Title}" Width="1.2*"/><DataGridTextColumn Header="Last step" Binding="{Binding LastStep}" Width="1.6*"/><DataGridTextColumn Header="Next step" Binding="{Binding NextStep}" Width="1.15*"/></DataGrid.Columns></DataGrid>
   <DockPanel Grid.Row="2"><Button x:Name="BtnDelete" DockPanel.Dock="Right" Content="Delete case"/><TextBlock x:Name="TxtListStatus" Text="No case selected" Foreground="{DynamicResource MutedText}" VerticalAlignment="Center" TextWrapping="Wrap"/></DockPanel>
  </Grid>
 </Border>
 <GridSplitter Grid.Column="1" Width="7" HorizontalAlignment="Stretch"/>
 <Border Grid.Column="2" Background="{DynamicResource CardBackground}" BorderBrush="{DynamicResource CardBorder}" BorderThickness="1" CornerRadius="6" Padding="8">
  <Grid><Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="*"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
   <WrapPanel Grid.Row="0"><Button x:Name="BtnReceive" Content="Receive file..."/><Button x:Name="BtnHandoff" Content="Create handoff"/><Button x:Name="BtnFolder" Content="Open folder"/><Button x:Name="BtnSave" Content="Save"/><TextBlock Text="Transport" VerticalAlignment="Center" Margin="10,0,3,0"/><ComboBox x:Name="CmbTransport" Width="145"/><Button x:Name="BtnAuto" Content="AUTO" FontWeight="Bold" MinWidth="90"/><Button x:Name="BtnCancel" Content="CANCEL" MinWidth="80"/><Button x:Name="BtnRefresh" Content="Refresh"/></WrapPanel>
   <Grid Grid.Row="1" Margin="0,5"><Grid.ColumnDefinitions><ColumnDefinition Width="Auto"/><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><Button x:Name="BtnLast" Content="Last Step" MinWidth="190" MaxWidth="360"/><TextBlock x:Name="TxtPosition" Grid.Column="1" HorizontalAlignment="Center" VerticalAlignment="Center" FontWeight="SemiBold"/><Button x:Name="BtnNext" Grid.Column="2" Content="Current" MinWidth="190" MaxWidth="360"/></Grid>
   <Border Grid.Row="2" Background="{DynamicResource StatusBackground}" BorderBrush="{DynamicResource CardBorder}" BorderThickness="1" CornerRadius="5" Padding="7" Margin="0,0,0,6"><Grid><Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/></Grid.RowDefinitions><TextBlock x:Name="TxtProgress" Text="Select a case" TextWrapping="Wrap"/><ProgressBar x:Name="PrgProgress" Grid.Row="1" Height="8" Margin="0,5,0,0" Minimum="0" Maximum="100"/></Grid></Border>
   <ScrollViewer Grid.Row="3" VerticalScrollBarVisibility="Auto"><StackPanel Margin="1"><TextBlock x:Name="TxtHeader" Text="Select or create a case" FontSize="19" FontWeight="SemiBold" Margin="0,0,0,6"/><Grid><Grid.ColumnDefinitions><ColumnDefinition Width="72"/><ColumnDefinition Width="*"/><ColumnDefinition Width="55"/><ColumnDefinition Width="190"/></Grid.ColumnDefinitions><TextBlock Text="Title" VerticalAlignment="Center"/><TextBox x:Name="TxtTitle" Grid.Column="1"/><TextBlock Grid.Column="2" Text="Type" Margin="8,0,0,0" VerticalAlignment="Center"/><ComboBox x:Name="CmbType" Grid.Column="3"/></Grid><TextBlock Text="Description / goal" FontWeight="SemiBold" Margin="0,6,0,2"/><TextBox x:Name="TxtDescription" AcceptsReturn="True" TextWrapping="Wrap" MinHeight="65" MaxHeight="120" VerticalScrollBarVisibility="Auto"/>
    <Expander Header="References and evidence" IsExpanded="True" Margin="0,7,0,4"><Border Background="{DynamicResource CardAltBackground}" BorderBrush="{DynamicResource CardBorder}" BorderThickness="1" CornerRadius="5" Padding="6"><Grid><Grid.RowDefinitions><RowDefinition Height="*"/><RowDefinition Height="Auto"/></Grid.RowDefinitions><DataGrid x:Name="DgRefs" AutoGenerateColumns="False" IsReadOnly="True" CanUserAddRows="False" MinHeight="100" MaxHeight="190"><DataGrid.Columns><DataGridTextColumn Header="Kind" Binding="{Binding Kind}" Width="90"/><DataGridTextColumn Header="Source" Binding="{Binding Source}" Width="1.2*"/><DataGridTextColumn Header="Mode" Binding="{Binding Mode}" Width="95"/><DataGridTextColumn Header="Selection" Binding="{Binding Selection}" Width="2*"/></DataGrid.Columns></DataGrid><WrapPanel Grid.Row="1" Margin="0,4,0,0"><Button x:Name="BtnAddPak" Content="Add PAK..."/><Button x:Name="BtnAddModFamily" Content="Add mod family..."/><Button x:Name="BtnAddVanilla" Content="Add Vanilla family..."/><Button x:Name="BtnRemoveRef" Content="Remove"/></WrapPanel></Grid></Border></Expander>
    <Expander Header="Requested / pending work" IsExpanded="False" Margin="0,3"><Border Background="{DynamicResource CardAltBackground}" BorderBrush="{DynamicResource CardBorder}" BorderThickness="1" CornerRadius="5" Padding="6"><TextBlock x:Name="TxtPending" Text="No pending work" TextWrapping="Wrap"/></Border></Expander>
    <TextBlock Text="History" FontSize="16" FontWeight="SemiBold" Margin="0,8,0,2"/><TextBlock Text="Newest first. Steps are collapsed by default; jump directly to any point." Foreground="{DynamicResource MutedText}"/><StackPanel x:Name="PnlHistory" Margin="0,4,0,0"/>
   </StackPanel></ScrollViewer>
   <TextBlock x:Name="TxtStatus" Grid.Row="4" Foreground="{DynamicResource MutedText}" TextWrapping="Wrap" Margin="1,5,1,0"/>
  </Grid>
 </Border>
</Grid>
</TabItem>
'@
  [xml]$xml=$x;$reader=New-Object System.Xml.XmlNodeReader $xml;$tab=[Windows.Markup.XamlReader]::Load($reader)
  foreach($n in @('BtnNew','DgCases','BtnDelete','TxtListStatus','BtnReceive','BtnHandoff','BtnFolder','BtnSave','CmbTransport','BtnAuto','BtnCancel','BtnRefresh','BtnLast','BtnNext','TxtPosition','TxtProgress','PrgProgress','TxtHeader','TxtTitle','CmbType','TxtDescription','DgRefs','BtnAddPak','BtnAddModFamily','BtnAddVanilla','BtnRemoveRef','TxtPending','PnlHistory','TxtStatus')){$Script:PMMAIIOCaseUI[$n]=$tab.FindName($n)}
  return $tab
}

function Get-PMMAIIOCaseRows{return @(Get-PMMAIIOCases|ForEach-Object{[pscustomobject]@{CaseId=[string]$_.CaseId;Title=[string]$_.Title;LastStep=[string]$_.LastAction;NextStep=(Get-PMMAIIOCaseNextLabel ([string]$_.NextAction))}})}
function Select-PMMAIIOCaseRow([string]$Id){$g=Get-PMMAIIOCaseControl 'DgCases';foreach($r in @($g.ItemsSource)){if([string]$r.CaseId -eq $Id){$g.SelectedItem=$r;$g.ScrollIntoView($r);return}}}
function Refresh-PMMAIIOCaseList([string]$SelectId=''){$g=Get-PMMAIIOCaseControl 'DgCases';if(-not$g){return};$keep=if($SelectId){$SelectId}elseif($Script:PMMAIIOCaseSelectedId){$Script:PMMAIIOCaseSelectedId}else{''};$g.ItemsSource=Get-PMMAIIOCaseRows;if($keep){Select-PMMAIIOCaseRow $keep}elseif(@($g.ItemsSource).Count -gt 0){$g.SelectedIndex=0}else{$Script:PMMAIIOCaseSelectedId='';Show-PMMAIIOCaseEditor}}

function Set-PMMAIIOCaseNextHighlight($Case){foreach($n in @('BtnReceive','BtnHandoff','BtnAuto')){$b=Get-PMMAIIOCaseControl $n;if($b){$b.ClearValue([System.Windows.Controls.Control]::BorderBrushProperty);$b.ClearValue([System.Windows.Controls.Control]::BorderThicknessProperty)}};if(-not$Case){return};$target=$(if([string]$Case.NextAction -eq 'WAIT_FOR_AI'){'BtnReceive'}elseif([string]$Case.NextAction -in @('CREATE_HANDOFF','EDIT_OR_CREATE_HANDOFF')){'BtnHandoff'}elseif([string]$Case.NextAction -eq 'PROCESS_REQUESTS'){'BtnAuto'}else{''});if($target){$b=Get-PMMAIIOCaseControl $target;$brush=$null;try{$hex=[string]$Script:ActiveThemeColorFlow.Import.Border;$brush=[Windows.Media.SolidColorBrush]([Windows.Media.ColorConverter]::ConvertFromString($hex))}catch{try{$brush=$Window.Resources['AccentBlue']}catch{}};if($b -and $brush){$b.BorderBrush=$brush;$b.BorderThickness=[Windows.Thickness]::new(2)}}}

function Show-PMMAIIOHistory($Case){$p=Get-PMMAIIOCaseControl 'PnlHistory';$p.Children.Clear();if(-not$Case){return};foreach($s in @(Get-PMMAIIOCaseSteps ([string]$Case.CaseId))){$n=[int]$s.StepNumber;$exp=[Windows.Controls.Expander]::new();$exp.IsExpanded=$false;$exp.Margin=[Windows.Thickness]::new(0,2,0,2);$border=[Windows.Controls.Border]::new();$border.BorderBrush=$Window.Resources['CardBorder'];$border.BorderThickness=[Windows.Thickness]::new(1);$border.CornerRadius=[Windows.CornerRadius]::new(4);$border.Padding=[Windows.Thickness]::new(6);$grid=[Windows.Controls.Grid]::new();$grid.ColumnDefinitions.Add([Windows.Controls.ColumnDefinition]::new());$c2=[Windows.Controls.ColumnDefinition]::new();$c2.Width=[Windows.GridLength]::Auto;$grid.ColumnDefinitions.Add($c2);$text=[Windows.Controls.TextBlock]::new();$text.Text=[string]$s.Summary;$text.TextTrimming='CharacterEllipsis';$text.VerticalAlignment='Center';$grid.Children.Add($text)|Out-Null;$btn=[Windows.Controls.Button]::new();$btn.Content=$(if($n -eq [int]$Case.CurrentStep){'[current]'}else{'[Step '+$n+']'});$btn.Tag=$n;[Windows.Controls.Grid]::SetColumn($btn,1);$grid.Children.Add($btn)|Out-Null;$handler={param($sender,$e)try{Set-PMMAIIOCaseSelectedStep $Script:PMMAIIOCaseSelectedId ([int]$sender.Tag)|Out-Null;Show-PMMAIIOCaseEditor}catch{Handle-UIError $_ 'Open AIIO step'}};$btn.Add_Click($handler);$exp.Header=$grid;$body=[Windows.Controls.TextBlock]::new();$body.Text=('Step '+$n+' · '+[string]$s.Kind+' · '+[string]$s.Utc+'`n'+[string]$s.Summary);$body.TextWrapping='Wrap';$body.Foreground=$Window.Resources['MutedText'];$border.Child=$body;$exp.Content=$border;$p.Children.Add($exp)|Out-Null}}

function Get-PMMAIIOReferenceRows($Case){$rows=[Collections.Generic.List[object]]::new();$i=0;foreach($r in @($Case.References.Mods)){$rows.Add([pscustomobject]@{Bucket='Mods';Index=$i;Kind='Mod';Source=[string]$r.Name;Mode=[string]$r.Mode;Selection=$(if([string]$r.Mode -eq 'FAMILIES'){@($r.Families)-join ', '}else{'Full PAK'})});$i++};$i=0;foreach($r in @($Case.References.VanillaFamilies)){$rows.Add([pscustomobject]@{Bucket='Vanilla';Index=$i;Kind='Vanilla';Source=[IO.Path]::GetFileName([string]$r.LogicalPath);Mode='Family';Selection=[string]$r.LogicalPath});$i++};return @($rows.ToArray())}
function Show-PMMAIIOCaseEditor{$c=Get-PMMAIIOSelectedCase;$controls=@('TxtTitle','CmbType','TxtDescription','CmbTransport','BtnSave','BtnHandoff','BtnFolder','BtnAuto','BtnCancel','BtnLast','BtnNext','BtnAddPak','BtnAddModFamily','BtnAddVanilla','BtnRemoveRef');foreach($n in $controls){$x=Get-PMMAIIOCaseControl $n;if($x){$x.IsEnabled=($null -ne $c)}};if(-not$c){(Get-PMMAIIOCaseControl 'TxtHeader').Text='Select or create a case';(Get-PMMAIIOCaseControl 'TxtPosition').Text='';(Get-PMMAIIOCaseControl 'TxtProgress').Text='No case selected';(Get-PMMAIIOCaseControl 'PrgProgress').Value=0;(Get-PMMAIIOCaseControl 'DgRefs').ItemsSource=@();(Get-PMMAIIOCaseControl 'PnlHistory').Children.Clear();Set-PMMAIIOCaseNextHighlight $null;return};$view=$c;$historical=([int]$c.SelectedStep -gt 0 -and [int]$c.SelectedStep -lt [int]$c.CurrentStep);if($historical){$s=Get-PMMAIIOCaseStep ([string]$c.CaseId) ([int]$c.SelectedStep);if($s){$view=$s.State}};(Get-PMMAIIOCaseControl 'TxtHeader').Text=([string]$c.Title+$(if($historical){' — historical Step '+[int]$c.SelectedStep}else{''}));(Get-PMMAIIOCaseControl 'TxtTitle').Text=[string]$view.Title;(Get-PMMAIIOCaseControl 'CmbType').SelectedValue=[string]$view.Type;(Get-PMMAIIOCaseControl 'TxtDescription').Text=[string]$view.Description;(Get-PMMAIIOCaseControl 'CmbTransport').SelectedValue=[string]$view.Transport;(Get-PMMAIIOCaseControl 'DgRefs').ItemsSource=Get-PMMAIIOReferenceRows $view;$pending=@($view.PendingActions|Where-Object{[string]$_.Status -eq 'Pending'});(Get-PMMAIIOCaseControl 'TxtPending').Text=$(if($pending.Count){@($pending|ForEach-Object{[string]$_.Action}) -join ', '}else{'No pending work.'});$op=$c.ActiveOperation;(Get-PMMAIIOCaseControl 'TxtProgress').Text=$(if($op.Message){[string]$op.Message}else{[string]$c.LastAction});$bar=Get-PMMAIIOCaseControl 'PrgProgress';$bar.IsIndeterminate=[bool]$op.Indeterminate;$bar.Value=$(if([int]$op.Total -gt 0){[Math]::Min(100,[Math]::Floor(100.0*[int]$op.Current/[int]$op.Total))}else{0});$pos=[int]$c.SelectedStep;if($pos -le 0){$pos=[int]$c.CurrentStep};(Get-PMMAIIOCaseControl 'TxtPosition').Text=('Step '+$pos+' / '+[int]$c.CurrentStep);$last=Get-PMMAIIOCaseControl 'BtnLast';$next=Get-PMMAIIOCaseControl 'BtnNext';$prev=if($pos -gt 1){Get-PMMAIIOCaseStep ([string]$c.CaseId) ($pos-1)}else{$null};$after=if($pos -lt [int]$c.CurrentStep){Get-PMMAIIOCaseStep ([string]$c.CaseId) ($pos+1)}else{$null};$last.Content=$(if($prev){'Last Step · '+[string]$prev.Summary}else{'Last Step'});$last.IsEnabled=($pos -gt 1);$next.Content=$(if($after){'Next Step · '+[string]$after.Summary}else{'Current · '+[string]$c.LastAction});$next.IsEnabled=($pos -lt [int]$c.CurrentStep);foreach($n in @('TxtTitle','CmbType','TxtDescription','CmbTransport','BtnSave','BtnAddPak','BtnAddModFamily','BtnAddVanilla','BtnRemoveRef','BtnAuto')){(Get-PMMAIIOCaseControl $n).IsEnabled=(-not$historical)};(Get-PMMAIIOCaseControl 'BtnHandoff').IsEnabled=$true;Show-PMMAIIOHistory $c;Set-PMMAIIOCaseNextHighlight $c;(Get-PMMAIIOCaseControl 'TxtListStatus').Text=([string]$c.Type+' · '+[string]$c.Status)}

function Save-PMMAIIOCaseEditor{$c=Get-PMMAIIOSelectedCase;if(-not$c){return};if([int]$c.SelectedStep -lt [int]$c.CurrentStep){return};$c.Title=[string](Get-PMMAIIOCaseControl 'TxtTitle').Text;$c.Type=Normalize-PMMAIIOCaseType ([string](Get-PMMAIIOCaseControl 'CmbType').SelectedValue);$c.Description=[string](Get-PMMAIIOCaseControl 'TxtDescription').Text;$c.Transport=Normalize-PMMAIIOCaseTransport ([string](Get-PMMAIIOCaseControl 'CmbTransport').SelectedValue);Save-PMMAIIOCase $c|Out-Null}
function Show-PMMAIIOTextPrompt([string]$Title,[string]$Label,[string]$Default=''){$f=[System.Windows.Forms.Form]::new();$f.Text=$Title;$f.Width=700;$f.Height=190;$f.StartPosition='CenterScreen';$l=[System.Windows.Forms.Label]::new();$l.Text=$Label;$l.Left=15;$l.Top=15;$l.Width=650;$t=[System.Windows.Forms.TextBox]::new();$t.Left=15;$t.Top=45;$t.Width=650;$t.Text=$Default;$ok=[System.Windows.Forms.Button]::new();$ok.Text='OK';$ok.Left=490;$ok.Top=90;$ok.DialogResult='OK';$cancel=[System.Windows.Forms.Button]::new();$cancel.Text='Cancel';$cancel.Left=575;$cancel.Top=90;$cancel.DialogResult='Cancel';$f.Controls.AddRange(@($l,$t,$ok,$cancel));$f.AcceptButton=$ok;$f.CancelButton=$cancel;if($f.ShowDialog() -eq 'OK'){return [string]$t.Text};return ''}
function Show-PMMAIIONewCaseDialog{$f=[System.Windows.Forms.Form]::new();$f.Text='New AIIO case';$f.Width=650;$f.Height=360;$f.StartPosition='CenterScreen';$title=[System.Windows.Forms.TextBox]::new();$title.Left=20;$title.Top=35;$title.Width=590;$type=[System.Windows.Forms.ComboBox]::new();$type.Left=20;$type.Top=90;$type.Width=250;$type.DropDownStyle='DropDownList';[void]$type.Items.AddRange(@('New Mod','Fix Mod','Compatibility','Undefined / Research'));$type.SelectedIndex=0;$desc=[System.Windows.Forms.TextBox]::new();$desc.Left=20;$desc.Top=145;$desc.Width=590;$desc.Height=100;$desc.Multiline=$true;$ok=[System.Windows.Forms.Button]::new();$ok.Text='Create';$ok.Left=425;$ok.Top=265;$ok.DialogResult='OK';$cancel=[System.Windows.Forms.Button]::new();$cancel.Text='Cancel';$cancel.Left=515;$cancel.Top=265;$cancel.DialogResult='Cancel';foreach($x in @(@('Title',15),@('Type',70),@('Description / goal',125))){$l=[System.Windows.Forms.Label]::new();$l.Text=$x[0];$l.Left=20;$l.Top=$x[1];$l.Width=200;$f.Controls.Add($l)};$f.Controls.AddRange(@($title,$type,$desc,$ok,$cancel));$f.AcceptButton=$ok;$f.CancelButton=$cancel;if($f.ShowDialog() -ne 'OK'){return $null};$map=@{'New Mod'='NEW_MOD';'Fix Mod'='FIX_MOD';'Compatibility'='COMPATIBILITY';'Undefined / Research'='UNDEFINED'};return [pscustomobject]@{Title=[string]$title.Text;Type=$map[[string]$type.SelectedItem];Description=[string]$desc.Text}}

function Confirm-PMMAIIOInboundTrust([string]$Path){$msg="PMM will inspect and follow the instructions contained in this file. A trusted work order may request local files and may run CMD, PowerShell, EXE or other installed tools.`n`nOnly continue if you trust the file and the person/AI that created it.`n`nFile: $([IO.Path]::GetFileName($Path))`n`nContinue?";return ([Windows.MessageBox]::Show($msg,'Trust AIIO input?',[Windows.MessageBoxButton]::YesNo,[Windows.MessageBoxImage]::Warning) -eq [Windows.MessageBoxResult]::Yes)}
function Route-PMMAIIOLegacyFile([string]$Path){$hint=Get-PMMAIIOResponsePackageHint $Path;if([string]$hint.Kind -eq 'ThemeResponse'){Import-PMMThemeAIResponse $Path|Out-Null;return $null};$sid=[string]$hint.SessionId;if(-not$sid -and [string]$hint.CaseId){foreach($r in @(& $Script:PMMAIIOCaseOriginalGetSessions)){$s=Get-PMMAIIOSession ([string]$r.SessionId);if($s -and [string]$hint.CaseId -in @($s.CaseIds|ForEach-Object{[string]$_})){$sid=[string]$s.SessionId;break}}};if(-not$sid){throw 'Could not route this legacy AIIO file to an existing exchange.'};Import-PMMAIIOAnyResponseZip -ZipPath $Path -ExpectedSessionId $sid|Out-Null;Initialize-PMMAIIOCasesFromLegacySessions;$case=@(Get-PMMAIIOCases|Where-Object{[string]$_.LegacySessionId -eq $sid}|Select-Object -First 1);if($case.Count){$c=$case[0];$s=Get-PMMAIIOSession $sid;$c.Status=[string]$s.Status;$c.NextAction=$(if([string]$s.Status -eq 'NeedsData'){'PROCESS_REQUESTS'}elseif([string]$s.Status -eq 'CandidateReady'){'REVIEW_CANDIDATE'}else{'WAIT_FOR_AI'});Save-PMMAIIOCase $c|Out-Null;Add-PMMAIIOCaseStep $c 'LEGACY_RESPONSE' ('Received AI response: '+[IO.Path]::GetFileName($Path)) ([string]$c.NextAction) @($Path) $null|Out-Null;return (Get-PMMAIIOCase ([string]$c.CaseId))};return $null}
function Invoke-PMMAIIOReceiveUi{$dlg=[Microsoft.Win32.OpenFileDialog]::new();$dlg.Filter='AIIO files (*.zip;*.json)|*.zip;*.json|All files (*.*)|*.*';if($dlg.ShowDialog() -ne $true){return};$p=[string]$dlg.FileName;if(-not(Confirm-PMMAIIOInboundTrust $p)){return};$doc=Read-PMMAIIOWorkOrder $p;$c=if($doc){Import-PMMAIIOWorkOrder $p $doc -Trusted -AutoProcess}else{Route-PMMAIIOLegacyFile $p};if($c){$Script:PMMAIIOCaseSelectedId=[string]$c.CaseId;Refresh-PMMAIIOCaseList ([string]$c.CaseId)};Set-PMMAIIOCaseUiStatus ('Received '+[IO.Path]::GetFileName($p))}
function Invoke-PMMAIIOCreateHandoffUi{$c=Get-PMMAIIOSelectedCase;if(-not$c){return};Save-PMMAIIOCaseEditor;$n=[int]$c.SelectedStep;if($n -le 0){$n=[int]$c.CurrentStep};$r=New-PMMAIIOCaseHandoff ([string]$c.CaseId) $n;Refresh-PMMAIIOCaseList ([string]$c.CaseId);Set-PMMAIIOCaseUiStatus ('Handoff ready: '+[IO.Path]::GetFileName([string]$r.ZipPath));try{Start-Process explorer.exe -ArgumentList ('/select,"'+[string]$r.ZipPath+'"')}catch{}}

function Initialize-PMMAIIOCaseWorkspaceUI{
  if($Script:PMMAIIOCaseWorkspaceInitialized){return};$Script:PMMAIIOCaseWorkspaceInitializing=$true;try{Initialize-PMMAIIOCasesFromLegacySessions;$tab=New-PMMAIIOCaseWorkspaceTab;if($Script:AIHelpTabs.Items.Count -ge 2){$Script:AIHelpTabs.Items.RemoveAt(1);$Script:AIHelpTabs.Items.RemoveAt(0)};$Script:AIHelpTabs.Items.Insert(0,$tab);$types=@([pscustomobject]@{Label='New Mod';Value='NEW_MOD'},[pscustomobject]@{Label='Fix Mod';Value='FIX_MOD'},[pscustomobject]@{Label='Compatibility';Value='COMPATIBILITY'},[pscustomobject]@{Label='Undefined / Research';Value='UNDEFINED'});$ct=Get-PMMAIIOCaseControl 'CmbType';$ct.ItemsSource=$types;$ct.DisplayMemberPath='Label';$ct.SelectedValuePath='Value';$tr=@([pscustomobject]@{Label='Auto';Value='AUTO'},[pscustomobject]@{Label='Manual ZIP';Value='MANUAL_ZIP'},[pscustomobject]@{Label='Agent server';Value='AGENT_SERVER'},[pscustomobject]@{Label='Git';Value='GIT'},[pscustomobject]@{Label='Nexus';Value='NEXUS'},[pscustomobject]@{Label='Link';Value='LINK'});$cm=Get-PMMAIIOCaseControl 'CmbTransport';$cm.ItemsSource=$tr;$cm.DisplayMemberPath='Label';$cm.SelectedValuePath='Value';$Script:PMMAIIOCaseProgressCallback={param($Id,$Current,$Total,$Message,$Indeterminate,$Completed)if($Id -eq $Script:PMMAIIOCaseSelectedId){$b=Get-PMMAIIOCaseControl 'PrgProgress';$b.IsIndeterminate=$Indeterminate;if(-not$Indeterminate -and $Total -gt 0){$b.Value=[Math]::Min(100,[Math]::Floor(100.0*$Current/$Total))};(Get-PMMAIIOCaseControl 'TxtProgress').Text=$Message;try{[void]$Window.Dispatcher.Invoke([Windows.Threading.DispatcherPriority]::Background,[action]{})}catch{}}}
  (Get-PMMAIIOCaseControl 'DgCases').Add_SelectionChanged({$r=(Get-PMMAIIOCaseControl 'DgCases').SelectedItem;if($r){$Script:PMMAIIOCaseSelectedId=[string]$r.CaseId;$c=Get-PMMAIIOCase $Script:PMMAIIOCaseSelectedId;if($c){$c.SelectedStep=[int]$c.CurrentStep;Save-PMMAIIOCase $c|Out-Null};Show-PMMAIIOCaseEditor}})
  (Get-PMMAIIOCaseControl 'BtnNew').Add_Click({try{$d=Show-PMMAIIONewCaseDialog;if($d){$c=New-PMMAIIOCase -Title $d.Title -Type $d.Type -Description $d.Description;$Script:PMMAIIOCaseSelectedId=[string]$c.CaseId;Refresh-PMMAIIOCaseList ([string]$c.CaseId)}}catch{Handle-UIError $_ 'Create AIIO case'}})
  (Get-PMMAIIOCaseControl 'BtnDelete').Add_Click({try{$c=Get-PMMAIIOSelectedCase;if($c -and [Windows.MessageBox]::Show(('Delete case "'+[string]$c.Title+'"?'),'Delete case',[Windows.MessageBoxButton]::YesNo,[Windows.MessageBoxImage]::Warning) -eq [Windows.MessageBoxResult]::Yes){Remove-PMMAIIOCase ([string]$c.CaseId);$Script:PMMAIIOCaseSelectedId='';Refresh-PMMAIIOCaseList}}catch{Handle-UIError $_ 'Delete AIIO case'}})
  (Get-PMMAIIOCaseControl 'BtnReceive').Add_Click({try{Invoke-PMMAIIOReceiveUi}catch{Handle-UIError $_ 'Receive AIIO file'}});(Get-PMMAIIOCaseControl 'BtnHandoff').Add_Click({try{Invoke-PMMAIIOCreateHandoffUi}catch{Handle-UIError $_ 'Create AIIO handoff'}});(Get-PMMAIIOCaseControl 'BtnSave').Add_Click({try{Save-PMMAIIOCaseEditor;Refresh-PMMAIIOCaseList $Script:PMMAIIOCaseSelectedId;Set-PMMAIIOCaseUiStatus 'Case saved.'}catch{Handle-UIError $_ 'Save case'}});(Get-PMMAIIOCaseControl 'BtnRefresh').Add_Click({try{Refresh-PMMAIIOCaseList}catch{Handle-UIError $_ 'Refresh cases'}})
  (Get-PMMAIIOCaseControl 'BtnFolder').Add_Click({$c=Get-PMMAIIOSelectedCase;if($c){Start-Process explorer.exe (Get-PMMAIIOCaseHandoffsPath ([string]$c.CaseId))}});(Get-PMMAIIOCaseControl 'BtnCancel').Add_Click({Stop-PMMAIIOCaseAutomation;Set-PMMAIIOCaseUiStatus 'Cancel requested.'});(Get-PMMAIIOCaseControl 'BtnAuto').Add_Click({try{$c=Get-PMMAIIOSelectedCase;if(-not$c){return};if([string]$c.NextAction -eq 'PROCESS_REQUESTS'){Invoke-PMMAIIOCasePendingActions ([string]$c.CaseId)|Out-Null}elseif([string]$c.NextAction -in @('CREATE_HANDOFF','EDIT_OR_CREATE_HANDOFF')){Invoke-PMMAIIOCreateHandoffUi;return}else{Set-PMMAIIOCaseUiStatus ('AUTO has no local action for '+[string]$c.NextAction)};Refresh-PMMAIIOCaseList ([string]$c.CaseId)}catch{Handle-UIError $_ 'AIIO AUTO'}})
  (Get-PMMAIIOCaseControl 'BtnLast').Add_Click({$c=Get-PMMAIIOSelectedCase;if($c -and [int]$c.SelectedStep -gt 1){Set-PMMAIIOCaseSelectedStep ([string]$c.CaseId) ([int]$c.SelectedStep-1)|Out-Null;Show-PMMAIIOCaseEditor}});(Get-PMMAIIOCaseControl 'BtnNext').Add_Click({$c=Get-PMMAIIOSelectedCase;if($c -and [int]$c.SelectedStep -lt [int]$c.CurrentStep){Set-PMMAIIOCaseSelectedStep ([string]$c.CaseId) ([int]$c.SelectedStep+1)|Out-Null;Show-PMMAIIOCaseEditor}})
  (Get-PMMAIIOCaseControl 'BtnAddPak').Add_Click({try{$c=Get-PMMAIIOSelectedCase;$d=[Microsoft.Win32.OpenFileDialog]::new();$d.Filter='PAK (*.pak)|*.pak';if($c -and $d.ShowDialog() -eq $true){Add-PMMAIIOCaseModReference ([string]$c.CaseId) ([string]$d.FileName) 'FULL_PAK'|Out-Null;Refresh-PMMAIIOCaseList ([string]$c.CaseId)}}catch{Handle-UIError $_ 'Add PAK'}})
  (Get-PMMAIIOCaseControl 'BtnAddModFamily').Add_Click({try{$c=Get-PMMAIIOSelectedCase;$d=[Microsoft.Win32.OpenFileDialog]::new();$d.Filter='PAK (*.pak)|*.pak';if($c -and $d.ShowDialog() -eq $true){$logical=Show-PMMAIIOTextPrompt 'Mod family' 'Exact logical .uasset path inside the PAK:';if($logical){Add-PMMAIIOCaseModReference ([string]$c.CaseId) ([string]$d.FileName) 'FAMILIES' @($logical)|Out-Null;Refresh-PMMAIIOCaseList ([string]$c.CaseId)}}}catch{Handle-UIError $_ 'Add mod family'}})
  (Get-PMMAIIOCaseControl 'BtnAddVanilla').Add_Click({try{$c=Get-PMMAIIOSelectedCase;$logical=Show-PMMAIIOTextPrompt 'Vanilla family' 'Exact Pal/Content/.../*.uasset logical path:';if($c -and $logical){Add-PMMAIIOCaseVanillaReference ([string]$c.CaseId) $logical|Out-Null;Refresh-PMMAIIOCaseList ([string]$c.CaseId)}}catch{Handle-UIError $_ 'Add Vanilla family'}})
  (Get-PMMAIIOCaseControl 'BtnRemoveRef').Add_Click({try{$c=Get-PMMAIIOSelectedCase;$r=(Get-PMMAIIOCaseControl 'DgRefs').SelectedItem;if($c -and $r){Remove-PMMAIIOCaseReference ([string]$c.CaseId) ([string]$r.Bucket) ([int]$r.Index)|Out-Null;Refresh-PMMAIIOCaseList ([string]$c.CaseId)}}catch{Handle-UIError $_ 'Remove reference'}})
  $Script:PMMAIIOCaseWorkspaceInitialized=$true;Refresh-PMMAIIOCaseList;Write-PMMLog 'AIIO Case Workspace V3 preview initialized.'}finally{$Script:PMMAIIOCaseWorkspaceInitializing=$false}}

# Lazy bootstrap: normal UI refresh calls Get-PMMAIIOSessions after XAML controls exist.
function Get-PMMAIIOSessions{$rows=@(& $Script:PMMAIIOCaseOriginalGetSessions);if(-not$Script:PMMAIIOCaseWorkspaceInitialized -and -not$Script:PMMAIIOCaseWorkspaceInitializing){$tabs=$null;try{$tabs=$Script:AIHelpTabs}catch{};if($tabs){try{Initialize-PMMAIIOCaseWorkspaceUI}catch{try{Write-PMMLog ('AIIO Case Workspace init failed: '+$_.Exception.Message)}catch{}}}};return $rows}
